-- tostring and tonumber: number formatting, bases 2-36, whitespace, junk, hex, exponents.
print(tostring(1), tostring(-1), tostring(0), tostring(1.5), tostring(-0.0), tostring(1e15), tostring(1e16))
print(tostring(100000000000000), tostring(1e14), tostring(123456789012345678), tostring(0.1), tostring(1/3))
print(tostring(3.14159265358979), tostring(2^53), tostring(2^63), tostring(1e-5), tostring(1e-4), tostring(123e-7))
print(tostring(12345.6789), tostring(0.30000000000000004), tostring(100 / 3), tostring(1e300 * 1e10))
print(tostring(true), tostring(false), tostring(nil), tostring("str"), tostring(""))
print(tonumber("10"), tonumber("  10  "), tonumber("\t10\n"), tonumber("10 x"), tonumber("x10"), tonumber(""), tonumber(" "))
print(tonumber("0x10"), tonumber("0X1f"), tonumber("-0x10"), tonumber("0x"), tonumber("0xg"), tonumber("1e1"), tonumber("1E+1"), tonumber("1e-1"))
print(tonumber("1."), tonumber(".1"), tonumber("."), tonumber("-.5"), tonumber("+.5"), tonumber("+5"), tonumber("--5"), tonumber("- 5"))
print(tonumber("1e"), tonumber("e1"), tonumber("1e1.5"), tonumber("0x1.8p1"), tonumber("1 e1"), tonumber("1,5"))
print(tonumber(5), tonumber(5.5), tonumber(nil), tonumber(true), tonumber({}), tonumber(print))
print(tonumber("10", 2), tonumber("11", 2), tonumber("12", 2), tonumber("ff", 16), tonumber("FF", 16), tonumber("fg", 16))
print(tonumber("zz", 36), tonumber("ZZ", 36), tonumber("10", 36), tonumber("7", 8), tonumber("8", 8), tonumber("10", 10))
print(tonumber("-10", 2), tonumber("-ff", 16), tonumber(" 11 ", 2), tonumber("1 1", 2), tonumber("", 2), tonumber("0x10", 16))
print(tonumber("1e1", 16), tonumber("1.5", 10), tonumber("777", 8), tonumber("101", 2), tonumber("2^3", 10))
print(tonumber("10", 2.0), tonumber("10", "2"), (pcall(tonumber, "10", 1)), (pcall(tonumber, "10", 37)))
print(tonumber("9007199254740993"), tonumber("1e308"), tonumber("1e309"), tonumber("-1e309"), tonumber("4.9e-324"), tonumber("1e-400"))
print(tonumber("00012"), tonumber("0x0010"), tonumber("1e0010"), tonumber("0.0000001"), tonumber("123456789012345678901234567890"))
print(tonumber("12abc"), tonumber("abc12"), tonumber("1 "), tonumber("\n1\n"), tonumber("1\0"), tonumber("\0001"))
print(tostring(tonumber("0x7fffffff")), tostring(tonumber("0xffffffff")), tostring(tonumber("0x100000000")))
print(tonumber("  0x10  "), tonumber("0x 10"), tonumber("0x1 0"), tonumber("1e5") == 100000, tonumber("5") == 5)
print(10 == tonumber("10"), "10" == 10, tostring(10) == "10", tostring(10.0) == "10", 10.0 == 10)
print(tostring(print):sub(1, 9), tostring({}):sub(1, 6), tostring(coroutine.create(print)):sub(1, 7))
print(type(tostring(print)), #tostring({}) > 7)
